def runs(row):
    R=[];i=0
    while i<len(row):
        if row[i]!=0:
            j=i
            while j<len(row) and row[j]==row[i]: j+=1
            R.append((i,j-1,row[i])); i=j
        else: i+=1
    return R
def solve(grid, pattern):
    pat={v:i for i,v in enumerate(pattern)}
    h,w=len(grid),len(grid[0])
    marks=[(r,a,b) for r,row in enumerate(grid) for a,b,_ in runs(row) if b-a==0]
    out=[row[:] for row in grid]
    for r,c,v in marks:
        o=pat[v]; L=len(pattern)
        options=[]
        if c-o>=0: options.append((c-o,'left'))
        if c+L-1-o<=w-1: options.append((c+L-1-o,'right'))
        # prefer side where cell is farther from edge? demo cell2 col7: left start = 7 (extends right); nearest-edge logic
        if options:
            best=min(options,key=lambda t:t[0]=='left'*(-1)+t[0] or 0)
            s=c-o if best=='left' else c+L-1-o
        else:
            continue
        for k,x in enumerate(pattern):
            out[r][s+k]=x
    return out
