def f(g):
    h,w=len(g),len(g[0]); out=[[0]*w for _ in range(h)]
    R=[]
    for r in range(h):
        c=0
        while c<w:
            if g[r][c]!=0:
                v=g[r][c]; j=c
                while j+1<w and g[r][j+1]==v: j+=1
                L=j-c+1
                if L>=2: R.append((r,c,v,L))
                c=j+1
            else: c+=1
    marks={(r,j) for r in range(h) for j in range(w) if g[r][j]!=(0)} 
    markset=set()
    for r_,c0,v,L in R:
        for j in range(c0,c0+L): markset.add((r_,j))
    seeds=[(r,c) for r in range(h) for c in range(w) if g[r][c] and (r,c) not in markset]
    def chb(a,b): return max(abs(a[0]-b[0]),abs(a[1]-b[1]))
    for sr,sc in seeds:
        v=g[sr][sc]
        best=None
        for r_,c0,val,L in R:
            if val!=v: continue
            d=min(max(abs(sr-r_),abs(sc-j)) for j in range(c0,c0+L))
            if best is None or d<best[0]: best=(d,r_,c0,val,L)
        d,r_,c0,val,L=best
        s=sc-c0
        for j in range(L):
            rr=s+j
            if 0<=rr<h: out[sr][sc+j]=val[j]
    return out
